import 'package:flutter/foundation.dart';

/// Output prediction generated by the on-device TFLite fusion model.
///
/// Contains the predicted skin condition label, top confidence score,
/// and full probability distribution across all supported classes.
@immutable
class Prediction {
  /// Top predicted class label (e.g., "Benign Keratosis", "Melanocytic Nevi").
  final String label;

  /// Top prediction confidence (0.0 to 1.0).
  final double confidence;

  /// Optional breakdown of class probabilities across all classes.
  final Map<String, double>? classProbabilities;

  const Prediction({
    required this.label,
    required this.confidence,
    this.classProbabilities,
  });

  /// Confidence formatted as percentage string (e.g. "87.5%").
  String get formattedConfidence => '${(confidence * 100).toStringAsFixed(1)}%';

  /// Creates a [Prediction] from JSON map.
  factory Prediction.fromJson(Map<String, dynamic> json) {
    Map<String, double>? probs;
    if (json['class_probabilities'] != null) {
      probs = (json['class_probabilities'] as Map<String, dynamic>).map(
        (key, value) => MapEntry(key, (value as num).toDouble()),
      );
    }
    return Prediction(
      label: json['label'] as String,
      confidence: (json['confidence'] as num).toDouble(),
      classProbabilities: probs,
    );
  }

  /// Converts this prediction to a JSON map.
  Map<String, dynamic> toJson() {
    return {
      'label': label,
      'confidence': confidence,
      if (classProbabilities != null) 'class_probabilities': classProbabilities,
    };
  }

  /// Creates a copy with optionally modified values.
  Prediction copyWith({
    String? label,
    double? confidence,
    Map<String, double>? classProbabilities,
  }) {
    return Prediction(
      label: label ?? this.label,
      confidence: confidence ?? this.confidence,
      classProbabilities: classProbabilities ?? this.classProbabilities,
    );
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Prediction &&
          runtimeType == other.runtimeType &&
          label == other.label &&
          confidence == other.confidence;

  @override
  int get hashCode => label.hashCode ^ confidence.hashCode;

  @override
  String toString() => 'Prediction(label: $label, confidence: $formattedConfidence)';
}

